create table kendurikita.mas_kahwin_rates(id uuid primary key default gen_random_uuid(), state text not null unique, amount numeric(12,2) not null check(amount>=0), typical_hantaran_min numeric(12,2) check(typical_hantaran_min>=0), typical_hantaran_max numeric(12,2) check(typical_hantaran_max>=typical_hantaran_min), source_url text not null, checked_at date not null, updated_by uuid references kendurikita.profiles(id));
create table kendurikita.savings_goals(id uuid primary key default gen_random_uuid(), event_id uuid not null unique references kendurikita.events(id) on delete cascade, target numeric(14,2) not null check(target>=0), current_amount numeric(14,2) not null default 0 check(current_amount>=0), reminder_day integer check(reminder_day between 1 and 28));
create table kendurikita.budget_contributions(id uuid primary key default gen_random_uuid(), event_id uuid not null references kendurikita.events(id) on delete cascade, contributor_id uuid references kendurikita.profiles(id), amount numeric(14,2) not null check(amount>0), note text, created_at timestamptz not null default now());
create table kendurikita.ai_usage(id uuid primary key default gen_random_uuid(), user_id uuid not null references kendurikita.profiles(id) on delete cascade, month date not null, request_count integer not null default 0 check(request_count>=0), unique(user_id,month));
create table kendurikita.vendor_bundles(id uuid primary key default gen_random_uuid(), owner_vendor_id uuid not null references kendurikita.vendors(id) on delete cascade, name text not null, price numeric(14,2) not null check(price>=0), active boolean not null default true);
create table kendurikita.vendor_bundle_members(bundle_id uuid references kendurikita.vendor_bundles(id) on delete cascade, vendor_id uuid references kendurikita.vendors(id) on delete cascade, package_id uuid references kendurikita.vendor_packages(id), commission_percent numeric(5,2) check(commission_percent between 0 and 100), primary key(bundle_id,vendor_id));
create table kendurikita.referrals(id uuid primary key default gen_random_uuid(), referrer_id uuid not null references kendurikita.profiles(id), referred_id uuid unique references kendurikita.profiles(id), code text not null, device_hash text, status text not null default 'pending', reward text, rewarded_at timestamptz, created_at timestamptz not null default now());
alter table kendurikita.mas_kahwin_rates enable row level security;alter table kendurikita.savings_goals enable row level security;alter table kendurikita.budget_contributions enable row level security;alter table kendurikita.ai_usage enable row level security;alter table kendurikita.vendor_bundles enable row level security;alter table kendurikita.vendor_bundle_members enable row level security;alter table kendurikita.referrals enable row level security;
create policy rates_public_read on kendurikita.mas_kahwin_rates for select using(true);
create policy savings_member_read on kendurikita.savings_goals for select using(kendurikita.is_event_member(event_id));create policy savings_editor_write on kendurikita.savings_goals for all using(kendurikita.can_edit_event(event_id)) with check(kendurikita.can_edit_event(event_id));
create policy contributions_member_read on kendurikita.budget_contributions for select using(kendurikita.is_event_member(event_id));create policy contributions_parent_write on kendurikita.budget_contributions for insert with check(exists(select 1 from kendurikita.event_members m where m.event_id=event_id and m.user_id=auth.uid()));
create policy ai_usage_self on kendurikita.ai_usage for select using(user_id=auth.uid());
create policy bundles_public_read on kendurikita.vendor_bundles for select using(active);create policy bundles_owner_write on kendurikita.vendor_bundles for all using(exists(select 1 from kendurikita.vendors v where v.id=owner_vendor_id and v.owner_id=auth.uid()));
create policy bundle_members_public_read on kendurikita.vendor_bundle_members for select using(exists(select 1 from kendurikita.vendor_bundles b where b.id=bundle_id and b.active));
create policy referrals_self on kendurikita.referrals for select using(referrer_id=auth.uid() or referred_id=auth.uid());
grant select on kendurikita.mas_kahwin_rates,kendurikita.vendor_bundles,kendurikita.vendor_bundle_members to anon,authenticated;grant select,insert,update,delete on kendurikita.savings_goals,kendurikita.budget_contributions,kendurikita.referrals to authenticated;
